static const ap_uint<8> expected[16] = {
    0x3Au, 0x7Fu, 0x11u, 0xC9u,
    0x04u, 0xD2u, 0x88u, 0x5Eu,
    0xB1u, 0x09u, 0x6Cu, 0xF0u,
    0x23u, 0xA7u, 0x5Bu, 0x1Du
};

ap_uint<1> check_token(const ap_uint<8> token[16]) {
    ap_uint<8> diff = 0;

    // Secret-derived flip bit (expected is secret).
    ap_uint<1> flip = (expected[0] & 1);

    for (int i = 0; i < 16; i = i + 1) {
        // Vulnerable: secret-dependent memory address pattern.
        int idx = i ^ (int)flip; // permutation depends on secret expected[0]
        ap_uint<8> t = token[idx];
        ap_uint<8> e = expected[idx];
        diff = (diff | (t ^ e));
    }

    ap_uint<1> result = (diff == 0);
    return result;
}

