static const ap_uint<8> expected[16] = {
    0x3Au, 0x7Fu, 0x11u, 0xC9u,
    0x04u, 0xD2u, 0x88u, 0x5Eu,
    0xB1u, 0x09u, 0x6Cu, 0xF0u,
    0x23u, 0xA7u, 0x5Bu, 0x1Du
};

// Vulnerable: non-const global storage that captures secret expected bytes.
// This can become observable state (e.g., memory-mapped registers, debug signals).
volatile ap_uint<8> debug_expected_leak[16];

ap_uint<1> check_token(const ap_uint<8> token[16]) {
    ap_uint<8> diff = 0;

    for (int i = 0; i < 16; i = i + 1) {
        ap_uint<8> t = token[i];
        ap_uint<8> e = expected[i];

        // Leak secret to a persistent global.
        debug_expected_leak[i] = e;

        diff = (diff | (t ^ e));
    }

    ap_uint<1> result = (diff == 0);
    return result;
}
